#include "q1_moe_hawkeye_bf16_accumulator.h"
#include <algorithm>
#include <array>
#include <cassert>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <stdexcept>
#include <vector>
namespace original=qrt_q1_moe_hawkeye;
using Value=original::Value;
struct Function {uint64_t b=0,c=0;unsigned s=0;};
uint64_t low(unsigned s){assert(s<64u);return (uint64_t(1)<<s)-1u;}
Function compose(Function f,Function g){
 if(g.s>=f.s){const uint64_t b=f.b+((f.c+g.b)&~low(f.s));return {b&low(g.s),g.c+(b&~low(g.s)),g.s};}
 return {f.b,g.c+((f.c+g.b)&~low(g.s)),f.s};
}
uint64_t evaluate(Function f,uint64_t x){return ((x+f.b)&~low(f.s))+f.c;}
bool regular(Value v){return !v.significand || (v.significand>=0x800000u&&v.significand<=0xffffffu&&v.exponent>=-126&&v.exponent<=127);}
bool equal(Value a,Value b){return a.significand==b.significand&&a.exponent==b.exponent&&(!a.significand||a.negative==b.negative);}
bool classification(Value a,Value b){return a.exponent==b.exponent&&(!a.significand==!b.significand)&&(!a.significand||a.negative==b.negative);}
float product_float(Value p){return std::ldexp(float(p.significand)*(p.negative?-1.f:1.f),p.exponent-23);}
Value from_integer(uint64_t bits,int base){
 const bool neg=bool(bits>>63u);const uint64_t mag=neg?0u-bits:bits;
 if(!mag)return {0u,-133,false};
 const unsigned width=original::bit_width_u64(mag);
 const int exponent=base+int(width)-1;
 if(width<24u||width>62u||exponent<-126||exponent>127)return {1u,-32768,false};
 const unsigned shift=width-24u;
 if(mag&low(shift))return {1u,-32768,false};
 return {uint32_t(mag>>shift),int16_t(exponent),neg};
}
uint64_t encode(Value v,int base){
 if(!v.significand)return 0u;
 const int shift=v.exponent-23-base;assert(shift>=0&&shift<=38);
 const uint64_t magnitude=uint64_t(v.significand)<<shift;
 return v.negative?0u-magnitude:magnitude;
}
uint32_t rng=0x3958192u;
uint32_t random_word(){rng^=rng<<13u;rng^=rng>>17u;return rng^=rng<<5u;}
struct Stats {size_t dots=0,blocks=0,domain=0,accepted=0,states=0,prediction_bad=0,raw_bad=0,full_dots=0,changed_binade=0,changed_sign=0;int maximum_span=0;};
template<unsigned Groups>
Value block(Value entry,const uint16_t* left,const uint16_t* right,Stats& stats,bool& dot_ok){
 ++stats.blocks;
 std::array<std::array<Value,16>,Groups> products;
 std::array<Value,Groups> reference,predicted,candidate;
 std::array<float,Groups> approximate,previous;
 std::array<int,Groups> maximum;
 std::array<int64_t,Groups> sums;
 std::array<Function,Groups> functions,prior;
 bool supported=regular(entry);
 for(unsigned g=0;g<Groups;++g){
  Value values[17];values[0]=g?reference[g-1]:entry;float partial=0;
  for(unsigned i=0;i<16;++i){
   const uint16_t a=left[g*16+i],b=right[g*16+i];
   const unsigned ae=(a>>7)&255u,be=(b>>7)&255u;
   supported=supported&&(!(a&0x7fffu)||(ae&&ae!=255))&&(!(b&0x7fffu)||(be&&be!=255));
   products[g][i]=values[i+1]=original::multiply_bf16(a,b,-133);
   partial+=product_float(values[i+1]);
  }
  approximate[g]=partial;
  reference[g]=original::group_sum<26,-133>(values,17);
 }
 // Predict without consulting any reference carry. Hillis-Steele snapshots
 // model simultaneous prefix updates; adding entry happens after the scan.
 for(unsigned step=1;step<Groups;step*=2){previous=approximate;for(unsigned g=step;g<Groups;++g)approximate[g]=previous[g-step]+previous[g];}
 for(unsigned g=0;g<Groups;++g){predicted[g]=original::value_from_float(original::value_to_float(entry)+approximate[g],-133);supported=supported&&regular(predicted[g]);}
 int base=10000,largest=-10000;
 for(unsigned g=0;g<Groups;++g){
  const Value incoming=g?predicted[g-1]:entry;int e=std::max(-133,int(incoming.exponent));
  for(auto p:products[g])e=std::max(e,int(p.exponent));
  maximum[g]=e;int64_t sum=0;
  for(auto p:products[g]){const unsigned shift=unsigned(e-p.exponent);const uint64_t m=shift>=32u?0u:(uint64_t(p.significand)<<2u)>>shift;sum+=p.negative?-int64_t(m):int64_t(m);}
  sums[g]=sum;base=std::min(base,e-25);largest=std::max(largest,e-25);
  if(predicted[g].significand)base=std::min(base,int(predicted[g].exponent)-23);
 }
 if(entry.significand)base=std::min(base,int(entry.exponent)-23);
 const int span=largest-base;stats.maximum_span=std::max(stats.maximum_span,span);
 supported=supported&&span<=30&&base>=-149;
 if(!supported){dot_ok=false;return reference.back();}
 ++stats.domain;
 for(unsigned g=0;g<Groups;++g){
  const Value incoming=g?predicted[g-1]:entry;
  const unsigned align=unsigned(maximum[g]-25-base);
  const int normalize=predicted[g].significand?int(predicted[g].exponent)-23-base:0;
  if(normalize<0||normalize>62){dot_ok=false;return reference.back();}
  const uint64_t shift_sum=uint64_t(sums[g])<<align;
  const Function alignment{incoming.negative?low(align):0u,shift_sum,align};
  const Function normalization{predicted[g].negative?low(unsigned(normalize)):0u,0u,unsigned(normalize)};
  functions[g]=compose(alignment,normalization);
 }
 // Independent simultaneous function prefix scan. The serial reference is
 // used only below to measure prediction coverage and check accepted states.
 for(unsigned step=1;step<Groups;step*=2){prior=functions;for(unsigned g=step;g<Groups;++g)functions[g]=compose(prior[g-step],prior[g]);}
 const uint64_t initial=encode(entry,base);bool accepted=true;
 for(unsigned g=0;g<Groups;++g){
  candidate[g]=from_integer(evaluate(functions[g],initial),base);
  accepted=accepted&&classification(candidate[g],predicted[g]);
  stats.prediction_bad+=!classification(reference[g],predicted[g]);
  ++stats.states;
  const auto incoming=g?reference[g-1]:entry;
  stats.changed_binade+=incoming.significand&&reference[g].significand&&incoming.exponent!=reference[g].exponent;
  stats.changed_sign+=incoming.significand&&reference[g].significand&&incoming.negative!=reference[g].negative;
 }
 if(accepted){++stats.accepted;for(unsigned g=0;g<Groups;++g){stats.raw_bad+=!equal(candidate[g],reference[g]);if(!equal(candidate[g],reference[g]))throw std::runtime_error("accepted state differs from canonical");}}
 else dot_ok=false;
 return reference.back();
}
std::vector<uint16_t> read(const char* path,size_t words){std::ifstream f(path,std::ios::binary|std::ios::ate);if(!f||f.tellg()!=std::streamoff(words*2u))throw std::runtime_error("input span");std::vector<uint16_t> v(words);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),v.size()*2u);if(!f)throw std::runtime_error("input read");return v;}
template<unsigned Groups>
void run(const std::vector<uint16_t>& x,const std::vector<uint16_t>& w,unsigned tokens,unsigned rows,unsigned width,bool attention){
 Stats stats;rng=0x3958192u;constexpr unsigned samples=8192;
 for(unsigned sample=0;sample<samples;++sample){
  const unsigned token=random_word()%tokens,row=attention?random_word()%(token+1):random_word()%rows,head=attention?random_word()%16:0;
  const auto* a=x.data()+(attention?(size_t(token)*16+head):size_t(token))*width;
  const auto* b=w.data()+(attention?(size_t(row)*2+head/8):size_t(row))*width;
  Value carry{0u,-133,false};bool all=true;
  for(unsigned k=0;k<width;k+=Groups*16)carry=block<Groups>(carry,a+k,b+k,stats,all);
  ++stats.dots;stats.full_dots+=all;
 }
 std::printf("{\"kind\":\"dyadic_scan_feasibility\",\"label\":\"uniform_captured_cells_not_filtered_candidates\",\"groups\":%u,\"width\":%u,\"attention\":%s,\"dots\":%zu,\"blocks\":%zu,\"supported_blocks\":%zu,\"accepted_blocks\":%zu,\"full_dots\":%zu,\"checked_states\":%zu,\"predicted_classification_mismatches\":%zu,\"canonical_binade_changes\":%zu,\"canonical_sign_changes\":%zu,\"maximum_alignment_span\":%d,\"accepted_raw_mismatches\":%zu,\"inference_acceptance\":false,\"performance_acceptance\":false}\n",Groups,width,attention?"true":"false",stats.dots,stats.blocks,stats.domain,stats.accepted,stats.full_dots,stats.states,stats.prediction_bad,stats.changed_binade,stats.changed_sign,stats.maximum_span,stats.raw_bad);
}
int main(int argc,char** argv)try{
 if(argc!=7)throw std::runtime_error("input weights tokens rows width attention");
 const unsigned tokens=unsigned(std::stoul(argv[3])),rows=unsigned(std::stoul(argv[4])),width=unsigned(std::stoul(argv[5]));const bool attention=std::stoul(argv[6])!=0;
 if(!tokens||!rows||(width!=256&&width!=2048&&width!=4096))throw std::runtime_error("shape");
 const auto x=read(argv[1],size_t(tokens)*width*(attention?16:1)),w=read(argv[2],size_t(rows)*width*(attention?2:1));
 run<8>(x,w,tokens,rows,width,attention);run<16>(x,w,tokens,rows,width,attention);
 if(!attention){run<32>(x,w,tokens,rows,width,attention);run<64>(x,w,tokens,rows,width,attention);}
 return 0;
}catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}

